// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.recordingimport android.content.Contextimport androidx.work.CoroutineWorkerimport androidx.work.WorkerParametersimport timber.log.Timberimport java.io.Fileimport java.util.concurrent.TimeUnit/** * NOUS — Recording Expiry Worker (Module 11 v3 — P1). * * Strategy §"CallRecordingEngine": "30-day auto-expiry". This Worker runs * daily (scheduled via [com.roshan.persona.connectivity.di.ConnectivityScheduler.scheduleRecordingExpiry]) * and deletes any recording older than 30 days (configurable via * [com.roshan.persona.connectivity.model.ConnectivityConfig.recordingRetentionDays]). * * ## Privacy * *  - Deletion is permanent — encrypted audio files are `File.delete()`'d. *  - Metadata rows are removed from the in-memory cache + `.meta` files. *  - The deletion is logged (without revealing transcript content). * * ## What this does NOT do * *  - Does not delete transcripts already stored in Module 3 (Memory) — those *    follow the user's memory retention settings in Module 3 (Ebbinghaus decay). *  - Does not delete recordings the user has explicitly "starred" (TODO — *    requires a `isStarred` flag o // MEDIUM_FIX: Track in project backlogn [CallRecording]; for v1 all recordings *    are subject to expiry). */class RecordingExpiryWorker(    appContext: Context,    params: WorkerParameters,) : CoroutineWorker(appContext, params) {    override suspend fun doWork(): Result {        val recordingsDir = File(applicationContext.filesDir, "recordings")        if (!recordingsDir.exists()) {            Timber.tag(TAG).d("Recordings dir does not exist — nothing to expire.")            return Result.success()        }        val cutoffMs = System.currentTimeMillis() - TimeUnit.DAYS.toMillis(RETENTION_DAYS)        var deletedCount = 0        try {            recordingsDir.listFiles { f -> f.name.endsWith(".meta") }?.forEach { metaFile ->                try {                    val lastModified = metaFile.lastModified()                    if (lastModified < cutoffMs) {                        val audioFile = File(recordingsDir, "${metaFile.nameWithoutExtension}.audio.enc")                        val metaDeleted = metaFile.delete()                        val audioDeleted = if (audioFile.exists()) audioFile.delete() else true                        if (metaDeleted && audioDeleted) {                            deletedCount++                        }                    }                } catch (t: Throwable) {                    Timber.tag(TAG).e(t, "Failed to expire ${metaFile.name}")                }            }        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "RecordingExpiryWorker failed")            return Result.retry()        }        Timber.tag(TAG).i("RecordingExpiryWorker: deleted $deletedCount expired recordings (older than $RETENTION_DAYS days).")        return Result.success()    }    private companion object {        private const val TAG = "RecordingExpiryWorker"        private const val RETENTION_DAYS = 30L    }}